import { mergeReferenceFood, type ReferenceFood, type ShelfLifeSource } from "../../lib/referenceMerge";
import type { MutationCtx } from "../_generated/server";
import fdaChart from "../data/fdaChart.json";
import foodkeeper from "../data/foodkeeper.json";

// Generated by convex/data/*.script.mjs; db writes still validate each row against the schema.
const DATASETS: [ReferenceFood[], ShelfLifeSource][] = [
  [fdaChart as ReferenceFood[], "fda_chart"],
  [foodkeeper as ReferenceFood[], "foodkeeper"],
];

// Upserts both datasets by name; FDA ranges win over FoodKeeper ones for the same location.
export async function importReferenceFoods(ctx: MutationCtx) {
  let inserted = 0;
  let updated = 0;
  for (const [rows, dataset] of DATASETS) {
    for (const row of rows) {
      const existing = await ctx.db
        .query("foods")
        .withIndex("by_name", (q) => q.eq("name", row.name))
        .unique();
      if (!existing) {
        await ctx.db.insert("foods", mergeReferenceFood(null, row));
        inserted++;
        continue;
      }
      const merged = mergeReferenceFood(existing, row, dataset);
      // The reference files carry no hasPrintedDate or webLookupAt, so keep the ones already set.
      await ctx.db.replace(existing._id, { ...merged, hasPrintedDate: existing.hasPrintedDate, webLookupAt: existing.webLookupAt });
      updated++;
    }
  }
  const total = (await ctx.db.query("foods").collect()).length;
  return { inserted, updated, total };
}
